import{_ as l,o as i,c as e,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"CDS Tentacle - RGW","description":"","frontmatter":{"title":"CDS Tentacle - RGW","date":"2024-08-22T00:00:00.000Z","updated":"2024-08-23T00:00:00.000Z","tags":["Ceph","分布式存储","RGW","S3 Select","Resharding","多站点","Zipper"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/CDS_Tentacle_-_RGW.md","filePath":"posts/2024/CDS_Tentacle_-_RGW.md","lastUpdated":1780459816000}'),n={name:"posts/2024/CDS_Tentacle_-_RGW.md"};function s(o,t,g,a,p,S){return i(),e("div",null,[...t[0]||(t[0]=[r("<p>本次会议主要讨论了Ceph分布式存储项目RGW的部分进展和未来计划，以下为会议关键内容：</p><p><strong>1. 扩展接口</strong></p><ul><li><strong>d4n缓存</strong>： 讨论了d4n缓存的使用和优化，包括完成读写缓存和缓存分配，以及考虑将非持久性数据缓存起来。</li><li><strong>S3 Select增强</strong>： 讨论了S3 Select的进一步增强，但目前Gal不在场，因此暂时保留此议题。</li><li><strong>Arrow flight</strong>： 讨论了Arrow flight的进一步优化，包括处理flight SQL请求并通过S3 Select进行增强。</li></ul><p><strong>2. 调整和优化</strong></p><ul><li><strong>Resharding</strong>： 讨论了Resharding的优化，包括非阻塞Resharding和Shard并发性。</li><li><strong>多站点</strong>： 讨论了多站点的优化，包括Bucket索引日志卸载到FIFO、复制清理和修复多站点测试。</li></ul><p><strong>3. Zipper</strong></p><ul><li><strong>Zipper可加载模块</strong>： 讨论了Zipper可加载模块的进展，目前Caleb正在开发中。</li><li><strong>灵活的配置</strong>： 讨论了灵活的配置，允许运行时配置Zipper的过滤器和存储。</li></ul><p><strong>4. 其他</strong></p><ul><li><strong>S3桶日志</strong>： 讨论了S3桶日志的实现，这是一个类似于AWS S3功能的特性，用于记录桶的所有修改和访问。</li><li><strong>大对象</strong>： 讨论了大对象的优化，包括使用相同的概念进行服务器端复制，并考虑将对象与数据分离。</li><li><strong>S3 put bucket所有权控制</strong>： 讨论了S3 put bucket所有权控制，允许禁用桶对象的ACL。</li><li><strong>跟踪</strong>： 讨论了跟踪的实现和优化，包括在rgw和OSD之间实现端到端跟踪，并讨论了如何使用跟踪来测量性能和定位问题。</li><li><strong>Lua强化</strong>： 讨论了Lua强化，包括防止Lua脚本消耗过多内存和CPU，以及防止Lua脚本修改操作系统或文件系统。</li><li><strong>C++ 20协程原型</strong>： 讨论了C++ 20协程原型，用于元数据同步，这将使多站点功能更容易实现。</li></ul><p><strong>行动计划</strong></p><ul><li>完成d4n缓存的优化和集成。</li><li>实现S3 Select的进一步增强。</li><li>优化Resharding和Shard并发性。</li><li>实现Bucket索引日志卸载到FIFO、复制清理和修复多站点测试。</li><li>开发Zipper可加载模块和灵活的配置。</li><li>实现S3桶日志和大对象优化。</li><li>禁用S3 put bucket所有权控制。</li><li>优化跟踪功能。</li><li>强化Lua功能。</li><li>开发C++ 20协程原型。</li></ul><p><strong>后续行动</strong></p><ul><li>将会议纪要中的讨论内容转化为Redmine跟踪问题。</li><li>继续推进各个议题的进展。</li><li>定期召开会议，讨论项目的进展和问题。</li></ul>",13)])])}const c=l(n,[["render",s]]);export{u as __pageData,c as default};
